tutions."}, {"id": "ebf1f8bd-a02c-4050-b608-c27dd840f736", "type": "subtopic", "title": "Nonstate actors", "children": [{"id": "99eb05dc-93e6-49d3-8eaf-762909aeba6b", "type": "concept", "title": "Multinational corporations"}, {"id": "12ff55a5-173e-4ca6-b05f-1c142ddb61a6", "type": "concept", "title": "NGOs and advocacy networks"}, {"id": "665d855a-ea2e-4e50-8f67-df877790856e", "type": "concept", "title": "Terrorist and criminal organizations"}], "description": "States are central, but they do not act alone."}, {"id": "cae702de-e38d-4ba5-ac31-dc22f42ab471", "type": "subtopic", "title": "Networks and influence", "children": [{"id": "9b63be15-ca6d-4ab8-9209-53936550eb44", "type": "concept", "title": "Diasporas"}, {"id": "fdc5e028-3d20-46a0-aa8e-060e51646112", "type": "concept", "title": "Media and information campaigns"}, {"id": "7860bc48-b549-4ae5-b2da-b4f8ee181881", "type": "concept", "title": "Norm diffusion and social movements"}], "description": "Power can move through networks as well as armies."}]}, {"id": "f0ebe8a7-0e0f-4641-b4f7-9f310ce9a2e5", "type": "topic", "title": "Climate, Migration, Health, Technology, and Emerging Global Issues", "description": "Students learn how IR tools apply to cross-border problems that do not fit neatly into old security or economic categories.", "children": [{"id": "a2af05cb-d13b-4454-a85a-d1087e928845", "type": "subtopic", "title": "Climate politics", "children": [{"id": "ba304136-e22f-435a-9ec7-7beff425ede0", "type": "concept", "title": "Paris Agreement"}, {"id": "ed861415-834b-45a3-b0ff-0967662856fd", "type": "concept", "title": "Mitigation and adaptation"}, {"id": "712463e6-aac2-4802-a777-263428b35e06", "type": "concept", "title": "Climate finance and loss-and-damage debates"}], "description": "Climate is a collective-action, justice, and security problem."}, {"id": "47303a39-6fb3-4ca3-a5dc-c0291ffe5476", "type": "subtopic", "title": "Migration and health", "children": [{"id": "805c0bc3-9932-4c07-bc0c-a6954018f988", "type": "concept", "title": "Refugees and asylum"}, {"id": "0cd1ae06-a84e-46df-966f-999a5a013565", "type": "concept", "title": "Pandemics and global health governance"}, {"id": "896443e4-7bb6-4db6-a8b9-93bd92937bcd", "type": "concept", "title": "Human security and border politics"}], "description": "Human mobility and disease reveal the limits of borders."}, {"id": "b977d811-c5df-4fb6-8cde-05fe588f078e", "type": "subtopic", "title": "Technology and cyber politics", "children": [{"id": "eb3cf57d-b0dc-4a98-909f-a3e958aeaa97", "type": "concept", "title": "Cyber conflict"}, {"id": "6a90ddfe-a065-45ff-b5de-0d80e79f4179", "type": "concept", "title": "AI governance"}, {"id": "18ab93d8-3ecd-47d9-9380-885ac1b5ccb0", "type": "concept", "title": "Space, surveillance, and digital authoritarianism"}], "description": "Technology creates new arenas of competition and governance."}]}, {"id": "204f9c17-437f-48d8-b78e-5b1a88805576", "type": "topic", "title": "Regions, Great Powers, and Contemporary World Order", "description": "This topic helps students interpret regional dynamics, great-power competition, U.S.-China relations, Russia, the EU, the Global South, and changing order.", "children": [{"id": "84cbf62a-a2c7-4b14-b4a1-25c586cddcf7", "type": "subtopic", "title": "Great-power competition", "children": [{"id": "f4ddf42f-0ec5-4737-aab6-58e3079b279a", "type": "concept", "title": "U.S.-China relations"}, {"id": "f1396468-34fb-4489-a77e-0e061822d620", "type": "concept", "title": "Russia and European security"}, {"id": "c6d2ea6b-9a2f-454a-bb11-103f89994ead", "type": "concept", "title": "India, middle powers, and regional actors"}], "description": "Students interpret how power shifts affect order."}, {"id": "c1cef7ea-533a-4aee-a3a2-8f26e5eb4bfb", "type": "subtopic", "title": "Regional orders", "children": [{"id": "c190a64a-4395-455d-826e-85b98b1e6f5f", "type": "concept", "title": "Europe and the EU"}, {"id": "8ec9449d-20cd-4ff3-a860-be47d13aa572", "type": "concept", "title": "Middle East and North Africa"}, {"id": "ccf84b78-6c95-46f3-8ae6-91179c806c15", "type": "concept", "title": "East Asia, Africa, and Latin America"}], "description": "Global politics is experienced differently across regions."}, {"id": "77674e45-14aa-45a3-be2e-21cb2c39488f", "type": "subtopic", "title": "World order debates", "children": [{"id": "9fa18c27-59fa-4af8-849b-2e69c3459b86", "type": "concept", "title": "Liberal international order"}, {"id": "c3dbcca6-d018-4d1c-a169-d4cfa7fc1680", "type": "concept", "title": "Revisionism and status quo powers"}, {"id": "265f149d-8763-4172-b2f7-7b0af1579726", "type": "concept", "title": "Global South and nonalignment"}], "description": "Students evaluate claims of unipolarity, multipolarity, and fragmentation."}]}, {"id": "ea3a5dbc-572a-4cd6-9491-92d636601bdc", "type": "topic", "title": "IR Capstone: Policy Brief and Theory-Guided Case Analysis", "description": "The course culminates in a case analysis that uses evidence and IR theory to explain an event and recommend a plausible policy response.", "children": [{"id": "9503e2f1-3f97-407d-8653-c87130e1edf1", "type": "subtopic", "title": "Case selection", "children": [{"id": "0326a6d6-7c80-474e-be5c-78e09c1ab13f", "type": "concept", "title": "Conflict, treaty, crisis, institution, or policy case"}, {"id": "e45bcdf2-e150-4bf2-b9e8-4753147f966f", "type": "concept", "title": "Historical background"}, {"id": "bf05e9c5-cc3a-46e7-85ac-11ccb18ce448", "type": "concept", "title": "Actors and stakes"}], "description": "Students choose a real IR problem that can be explained with evidence."}, {"id": "4c55acfb-8ded-4b33-866b-afade6e21662", "type": "subtopic", "title": "Theory-guided explanation", "children": [{"id": "84d25d6a-ef16-4430-b47d-9dd5f25d2921", "type": "concept", "title": "Realist explanation"}, {"id": "245e7289-e257-41e8-ab07-8d60c423eee7", "type": "concept", "title": "Liberal/institutionalist explanation"}, {"id": "c7c81bc0-c97b-4fc3-bdbf-938b70cc9f21", "type": "concept", "title": "Constructivist or critical explanation"}], "description": "The capstone tests theories against evidence."}, {"id": "abb90b09-0278-4d0f-85b7-f3f77dd43463", "type": "subtopic", "title": "Policy recommendation", "children": [{"id": "56725e1f-0962-478c-81a3-151c252a84af", "type": "concept", "title": "Options and tradeoffs"}, {"id": "cac24243-e501-461d-bc37-5d4c2bcb3bb2", "type": "concept", "title": "Risks and uncertainty"}, {"id": "8152f06b-429b-4b30-beff-ff4cd17beedd", "type": "concept", "title": "Briefing memo or presentation"}], "description": "Students convert analysis into a concise, plausible recommendation."}]}], "dbBacked": true}$ireljson$::jsonb,
