update public.learning_paths
set
  title = 'Introduction to International Relations',
  goal = 'Introduction to International Relations',
  summary = 'Students learn what IR studies, how to ask causal questions about world politics, and how individual, state, domestic, and system-level explanations differ. Core goals cover power, anarchy, and the security dilemma; cooperation through institutions, domestic politics, trade, and repeated interaction; ideas, identities, norms, and legitimacy; critical approaches to inequality, hierarchy, gender, empire, capitalism, and silenced voices; war, deterrence, alliances, and security; foreign policy decision-making; treaties, sovereignty, and international organizations; trade, finance, development, and sanctions; global governance; human rights, humanitarian intervention, and accountability; corporations, NGOs, and other nonstate actors; climate, migration, health, and technology; and regional dynamics, great-power competition, and changing world order.',
  data = $ireljson${"slug": "introduction-to-international-relations", "title": "Introduction to International Relations", "description": "Students learn what IR studies, how to ask causal questions about world politics, and how individual, state, domestic, and system-level explanations differ. Core goals cover power, anarchy, and the security dilemma; cooperation through institutions, domestic politics, trade, and repeated interaction; ideas, identities, norms, and legitimacy; critical approaches to inequality, hierarchy, gender, empire, capitalism, and silenced voices; war, deterrence, alliances, and security; foreign policy decision-making; treaties, sovereignty, and international organizations; trade, finance, development, and sanctions; global governance; human rights, humanitarian intervention, and accountability; corporations, NGOs, and other nonstate actors; climate, migration, health, and technology; and regional dynamics, great-power competition, and changing world order.", "topics": [{"id": "4541737b-9c31-4a70-816f-55b6c0968318", "type": "topic", "title": "The Study of International Relations and Levels of Analysis", "description": "Students learn what IR studies, how to ask causal questions about world politics, and how individual, state, domestic, and system-level explanations differ.", "children": [{"id": "d03c5efe-dfdb-4871-baca-7e9e0b98c198", "type": "subtopic", "title": "What IR explains", "children": [{"id": "12e4d587-c53a-49fa-b6ab-38945beec053", "type": "concept", "title": "War and peace"}, {"id": "094a407f-5f53-46e9-9424-fcb50a34fdc5", "type": "concept", "title": "Cooperation and conflict"}, {"id": "9312f08f-35fc-48c4-84bf-f61ab5dc768b", "type": "concept", "title": "Order, change, and hierarchy"}], "description": "Students learn the basic puzzles of world politics."}, {"id": "df3efa8b-bd82-4ea0-970d-471e81f3b008", "type": "subtopic", "title": "Levels of analysis", "children": [{"id": "9a5fb165-cf6c-40aa-b399-d6570a25a004", "type": "concept", "title": "Individual leaders and psychology"}, {"id": "dd678921-4553-4f9c-ab58-84cecd410441", "type": "concept", "title": "Domestic politics and regime type"}, {"id": "2e801d53-f624-4a54-9057-1baea5ecb1ec", "type": "concept", "title": "International system and distribution of power"}], "description": "Different levels help avoid one-cause explanations."}, {"id": "08b506f1-60de-4ebb-81ac-3d7463d04691", "type": "subtopic", "title": "Evidence and argument", "children": [{"id": "fe5742f1-68aa-46b2-918e-a5bb901a169d", "type": "concept", "title": "Case studies and comparison"}, {"id": "875738fb-0835-487b-8415-f43091d3065f", "type": "concept", "title": "Primary sources and data"}, {"id": "c79baf3a-767a-437f-a47b-02a25a9013c2", "type": "concept", "title": "Causal claims and alternative explanations"}], "description": "IR is strongest when theory is tied to evidence."}]}, {"id": "d40db278-1ed4-4c11-8214-f75dfcceaedf", "type": "topic", "title": "Realism, Power, Anarchy, and the Security Dilemma", "description": "This topic explains how power, survival, uncertainty, and anarchy shape state behavior and conflict.", "children": [{"id": "48a9f71b-698d-4ef4-9e9b-b4e6f64f6494", "type": "subtopic", "title": "Classical and structural realism", "children": [{"id": "f41cf8aa-a9ed-4b02-a975-8ecf16448aff", "type": "concept", "title": "Power and national interest"}, {"id": "6a9cccb5-8303-4844-938e-d426fea1c0f2", "type": "concept", "title": "Balance of power"}, {"id": "e7065e38-7834-4ec2-896a-9f713cac63f1", "type": "concept", "title": "Defensive and offensive realism"}], "description": "Realism asks how states pursue security under anarchy."}, {"id": "67ed9506-1dc7-4b73-97ec-8dfa91e124c2", "type": "subtopic", "title": "Security dilemma", "children": [{"id": "e7a8194f-8cde-4c72-9650-e0a70b4e7de8", "type": "concept", "title": "Uncertainty and misperception"}, {"id": "13e2eba6-1d85-4182-bf60-6c191ec106f1", "type": "concept", "title": "Arms races"}, {"id": "1b819db1-c673-472e-bb44-b3e365a13bf0", "type": "concept", "title": "Commitment problems"}], "description": "Actions taken for defense can appear threatening to others."}, {"id": "460a054a-4759-4c8d-8a4c-228943eb7c99", "type": "subtopic", "title": "Realist policy tools", "children": [{"id": "fbd17d8f-c586-484e-aa5f-42fe05a4de6f", "type": "concept", "title": "Deterrence"}, {"id": "85768d16-0c56-43ea-ba2e-c5445ff8d241", "type": "concept", "title": "Alliances"}, {"id": "ffa5ce36-1309-4d94-a4bd-59bd71dd025a", "type": "concept", "title": "Spheres of influence and great-power rivalry"}], "description": "Students learn how realism interprets strategy."}]}, {"id": "89682305-6f32-4a7c-923b-06684320ed81", "type": "topic", "title": "Liberalism, Institutions, Interdependence, and Cooperation", "description": "Students learn why cooperation can occur despite anarchy through institutions, domestic politics, trade, and repeated interaction.", "children": [{"id": "0d2c88b6-972a-4810-ae2e-265ab66e4de7", "type": "subtopic", "title": "Liberal theories", "children": [{"id": "b88d5d1e-f193-402a-8100-583e80ad4fbe", "type": "concept", "title": "Democratic peace"}, {"id": "1145328b-8976-4b16-9703-a18aa8d7905e", "type": "concept", "title": "Commercial peace"}, {"id": "8cd6847e-8941-4994-849f-2d916baf6733", "type": "concept", "title": "Republican and neoliberal institutionalism"}], "description": "Liberalism explains cooperation through institutions, preferences, and domestic politics."}, {"id": "bc6a5548-8c47-4143-b9ba-a0b473b3ea90", "type": "subtopic", "title": "International institutions", "children": [{"id": "37062d55-5925-4b76-9b62-a8717493af12", "type": "concept", "title": "Information, monitoring, and transaction costs"}, {"id": "7eef2965-9a91-4aad-956f-777366734441", "type": "concept", "title": "Regimes and rules"}, {"id": "22c58140-1659-49ab-912d-0ac75db11e39", "type": "concept", "title": "Compliance and reciprocity"}], "description": "Institutions reduce uncertainty and support cooperation."}, {"id": "5635f3ce-7afc-49a5-a8ec-8b4ddee9efa6", "type": "subtopic", "title": "Interdependence", "children": [{"id": "55bd95b1-8d8c-450e-9193-b9d817b73370", "type": "concept", "title": "Trade dependence"}, {"id": "21642b6c-091c-4d9d-b28b-dd778170cf6f", "type": "concept", "title": "Complex interdependence"}, {"id": "45d441a5-35ae-4e93-bf8a-a56e97f8636a", "type": "concept", "title": "Vulnerability and sensitivity"}], "description": "Economic and social ties can constrain or intensify conflict."}]}, {"id": "341f3069-1f26-468d-b6a2-266f3000eaaf", "type": "topic", "title": "Constructivism, Identity, Norms, and International Society", "description": "This module shows how ideas, identities, norms, and legitimacy shape interests and international order.", "children": [{"id": "50aec6db-5aba-419c-a9b9-650bf37a494f", "type": "subtopic", "title": "Norms and identity", "children": [{"id": "23a72461-a5cc-4e78-a961-64b2ae6ec738", "type": "concept", "title": "Norm entrepreneurs"}, {"id": "63cbc8a9-e9ff-46fa-b77c-632fbf70562b", "type": "concept", "title": "Socialization"}, {"id": "fe260642-589a-4321-88e8-3a55bf1ebc4f", "type": "concept", "title": "Identity and interests"}], "description": "Constructivism asks how actors understand who they are and what is appropriate."}, {"id": "ad04984b-674d-4ad5-a408-95bf73d46f72", "type": "subtopic", "title": "International society", "children": [{"id": "4c621d84-cfa7-4574-acd5-554d6d8e08c8", "type": "concept", "title": "English School basics"}, {"id": "ba6175d9-6ad5-441f-814a-592f9dcf3a2b", "type": "concept", "title": "Sovereignty as a social institution"}, {"id": "fc897836-7f07-448c-b95d-e9f85e4727bc", "type": "concept", "title": "Diplomacy and recognition"}], "description": "Rules and legitimacy shape behavior beyond material power."}, {"id": "76d183c8-5b7c-4e00-b6a2-39080dbee66d", "type": "subtopic", "title": "Norm change", "children": [{"id": "2e433c44-cebe-4e0c-8d28-280a4cda29bc", "type": "concept", "title": "Human rights norms"}, {"id": "e974ba3f-c4b6-47ca-bac8-78a83dda7f0e", "type": "concept", "title": "Anti-slavery and anti-apartheid campaigns"}, {"id": "88e3010e-6a25-4083-abb8-7e7d66ee5293", "type": "concept", "title": "Nuclear taboo and humanitarian norms"}], "description": "Students learn how ideas reshape global politics."}]}, {"id": "7bca0887-9b5a-4a25-b880-c23c7827aa95", "type": "topic", "title": "Critical, Marxist, Feminist, Postcolonial, and Global South Perspectives", "description": "Students learn how critical approaches reveal inequality, hierarchy, gender, empire, capitalism, and silenced voices in global politics.", "children": [{"id": "72034990-edf3-42ef-84e5-9090fa17106b", "type": "subtopic", "title": "Political economy and hierarchy", "children": [{"id": "83e74386-245c-4cb2-9ec4-983a48060384", "type": "concept", "title": "Dependency and world-systems thinking"}, {"id": "626b57a4-7818-481f-8f87-b898ca91e8ed", "type": "concept", "title": "Imperialism and extraction"}, {"id": "ab33c00f-5ad8-4962-8b22-98c9503c3856", "type": "concept", "title": "Global class relations"}], "description": "Critical theory examines power embedded in capitalism and global structures."}, {"id": "a4736604-3367-49c5-a515-b475fb00193f", "type": "subtopic", "title": "Feminist IR", "children": [{"id": "fea2ee8d-b7f4-4ca3-8d77-979b1967e623", "type": "concept", "title": "Gendered security"}, {"id": "3203044c-a248-4606-81c7-f24a036c7e3f", "type": "concept", "title": "Care work and global labor"}, {"id": "2ef11598-9d87-4d7b-8f19-f8fddb95bec0", "type": "concept", "title": "Women, peace, and security"}], "description": "Students learn how gender shapes security, diplomacy, war, and political economy."}, {"id": "3223886a-b818-4d07-abaa-4783b8c61cea", "type": "subtopic", "title": "Postcolonial and Global South IR", "children": [{"id": "a113881d-23e7-4de2-87ff-5c8df4321716", "type": "concept", "title": "Colonial legacies"}, {"id": "ea27a8ca-d27a-41f2-85ee-b6d533cfe648", "type": "concept", "title": "Race and empire"}, {"id": "120f0bfc-9635-4331-8cf5-7975504b4749", "type": "concept", "title": "Subaltern and Southern agency"}], "description": "These perspectives challenge Eurocentric stories of world politics."}]}, {"id": "ddd6b33d-e8d3-4499-b12b-65604ac1efa6", "type": "topic", "title": "War, Peace, Deterrence, and International Security", "description": "This topic covers causes of war, deterrence, alliances, nuclear weapons, civil war, terrorism, cyber threats, and nontraditional security.", "children": [{"id": "aca0c52e-618e-496d-890d-487ca8ae3fdb", "type": "subtopic", "title": "Causes of war", "children": [{"id": "adc3eba8-8749-4936-9ab9-2b55ae2c8710", "type": "concept", "title": "Territory, resources, commitment, and information problems"}, {"id": "d34e77ef-fdeb-40bc-b54c-df78e2494799", "type": "concept", "title": "Misperception and domestic politics"}, {"id": "3fa76aa5-5b13-4d01-81ae-b5c1df9dbb0e", "type": "concept", "title": "Civil and interstate war"}], "description": "Students compare explanations for why war occurs."}, {"id": "73a6bb30-01f1-4d97-be41-8b81813a37cc", "type": "subtopic", "title": "Deterrence and nuclear weapons", "children": [{"id": "fc69b87c-cc08-40b1-b381-f6247710bb0c", "type": "concept", "title": "Deterrence by denial and punishment"}, {"id": "fbce66f9-8592-4e96-ac89-d8e5be312584", "type": "concept", "title": "Nuclear proliferation"}, {"id": "4d3eab9d-184f-49e1-9036-18e3c34cdd4e", "type": "concept", "title": "Arms control and disarmament"}], "description": "Security strategy often depends on credible threats."}, {"id": "5622676d-5aee-4136-977e-277ae9dd78ce", "type": "subtopic", "title": "Contemporary security", "children": [{"id": "4506f236-8725-409c-a68e-4ad80412854b", "type": "concept", "title": "Terrorism and insurgency"}, {"id": "dbc0b2a5-2ce5-45df-a63e-0ebd6b25bafc", "type": "concept", "title": "Cybersecurity"}, {"id": "0979bda5-58bc-4b9f-926d-aff0c4203898", "type": "concept", "title": "Human, environmental, and health security"}], "description": "Security now includes military and nonmilitary threats."}]}, {"id": "0938e3c1-9ad1-4deb-9d7e-d4f0982d67d4", "type": "topic", "title": "Foreign Policy Analysis and Diplomatic Decision-Making", "description": "Students examine how leaders, bureaucracies, domestic politics, perception, and crisis conditions shape foreign policy choices.", "children": [{"id": "bb55abef-4064-43a7-9053-7e0fb5a97f19", "type": "subtopic", "title": "Decision-making models", "children": [{"id": "43ae918d-acf4-4950-9fa6-e7488c5cd7fa", "type": "concept", "title": "Rational actor model"}, {"id": "96a060f8-cdf1-4704-a106-c759c0423578", "type": "concept", "title": "Organizational process"}, {"id": "635f11b3-698f-433e-8743-2f6c04c0f2c0", "type": "concept", "title": "Bureaucratic politics"}], "description": "Foreign policy is made by people and organizations, not abstract states alone."}, {"id": "eb24c185-adfe-4101-bd62-ff02af3dcbfb", "type": "subtopic", "title": "Domestic sources", "children": [{"id": "b486da8d-5a8a-407b-8a23-044bc4af58c8", "type": "concept", "title": "Public opinion and media"}, {"id": "645f3df4-cc95-4ae5-8d50-049122e895a3", "type": "concept", "title": "Interest groups and legislatures"}, {"id": "5eba105d-008c-47a2-bec9-be61b0e8bc6e", "type": "concept", "title": "Regime type and coalitions"}], "description": "Internal politics often shape external behavior."}, {"id": "7a380d0f-2449-441e-8c94-257944faae7d", "type": "subtopic", "title": "Crisis diplomacy", "children": [{"id": "9fe473ac-e352-497d-be9d-58aa1d09539c", "type": "concept", "title": "Misperception"}, {"id": "ea68c95d-bf3d-42c6-8263-9e7e1f752c0a", "type": "concept", "title": "Groupthink"}, {"id": "7cf496dc-4147-46f8-b4ba-7a0202d4ab1d", "type": "concept", "title": "Negotiation, signaling, and escalation control"}], "description": "Students learn how pressure affects judgment."}]}, {"id": "9cb20fc0-9cbe-4e7a-b0c3-e4b7a0c25329", "type": "topic", "title": "International Law, Sovereignty, and International Organizations", "description": "This section introduces treaties, customary law, sovereignty, the UN system, courts, human rights law, and compliance problems.", "children": [{"id": "23d7010c-02d4-4abd-83ba-8055559a8cf5", "type": "subtopic", "title": "Sources of international law", "children": [{"id": "12b7c51b-ccaa-474b-ba9e-4ba0d773f726", "type": "concept", "title": "Treaties"}, {"id": "ee63582a-c1aa-4804-af31-f236ea7d81a9", "type": "concept", "title": "Customary international law"}, {"id": "3b01e0ed-83ca-46aa-b307-fd2eeff17499", "type": "concept", "title": "General principles and judicial decisions"}], "description": "Students learn where international legal obligations come from."}, {"id": "f6407722-8592-4790-b2c3-2db80eceeb1a", "type": "subtopic", "title": "Sovereignty and jurisdiction", "children": [{"id": "4fe8b6b7-aa0e-4d88-ba34-50e312c2fef2", "type": "concept", "title": "Recognition and statehood"}, {"id": "ebd65123-a06d-42cd-8efe-ae9c2733061f", "type": "concept", "title": "Territorial jurisdiction"}, {"id": "9b9eaa55-0667-4a35-b19e-30af3ec01660", "type": "concept", "title": "Responsibility and accountability"}], "description": "Law both protects and limits state power."}, {"id": "ff8ebf59-1db5-492e-81bb-19f718fe2834", "type": "subtopic", "title": "International organizations and courts", "children": [{"id": "4aa9b6fd-4cd1-4198-b92d-27ddfc143222", "type": "concept", "title": "United Nations"}, {"id": "330f63fb-48c7-4d30-8683-020c0230d691", "type": "concept", "title": "International Court of Justice"}, {"id": "e2a3c841-b23f-4c1e-b553-7c7bb3f46391", "type": "concept", "title": "International Criminal Court and dispute settlement"}], "description": "Institutions help coordinate, adjudicate, and legitimate action."}]}, {"id": "11360000-4473-4575-ab4f-f622586f709c", "type": "topic", "title": "International Political Economy: Trade, Finance, Development, and Sanctions", "description": "Students connect politics to trade, money, multinational firms, development, inequality, economic statecraft, and globalization.", "children": [{"id": "7f9ce0e3-6aa0-42d1-95c4-60e4d9e7bc1d", "type": "subtopic", "title": "Trade politics", "children": [{"id": "8e683f32-2f70-44ab-aebf-55567e2f02f8", "type": "concept", "title": "Comparative advantage"}, {"id": "9726b4e8-86b4-4b2e-a75b-4407a2315fdf", "type": "concept", "title": "Protectionism"}, {"id": "f931c15a-2b99-4b1b-a818-f317357cc9a9", "type": "concept", "title": "WTO and trade disputes"}], "description": "Trade creates gains and distributional conflicts."}, {"id": "66141a77-c878-490a-aa32-0deede32469b", "type": "subtopic", "title": "Money and finance", "children": [{"id": "506d36c4-92af-4800-a851-5dee55e550d7", "type": "concept", "title": "IMF, exchange rates, and crises"}, {"id": "c33b4383-9b04-43b0-9cec-61ae2a4ce362", "type": "concept", "title": "Debt and capital flows"}, {"id": "ca666b65-76a2-4672-a28b-7dc0dfa2a889", "type": "concept", "title": "Monetary order"}], "description": "International finance links domestic policy to global markets."}, {"id": "ac5dbbb9-3ad5-4eb2-8361-c01533101df1", "type": "subtopic", "title": "Development and economic statecraft", "children": [{"id": "6461ab8a-8b65-4efc-8e47-e1f5f60e0775", "type": "concept", "title": "World Bank and development"}, {"id": "61fa09c8-3a1a-4342-a72b-b957efaeb5f6", "type": "concept", "title": "Sanctions"}, {"id": "1e0a7a5a-307b-4051-90c6-a2496a1c01eb", "type": "concept", "title": "Inequality and globalization backlash"}], "description": "Economic tools are political tools."}]}, {"id": "ccfad89d-749c-4d2a-82ed-e4aad269f447", "type": "topic", "title": "Global Governance, Multilateralism, and International Institutions", "description": "This topic examines how states and nonstate actors cooperate through regimes, institutions, networks, and informal governance.", "children": [{"id": "2f1b9d2a-957a-4d7e-a5f7-a595b40c4315", "type": "subtopic", "title": "Cooperation problems", "children": [{"id": "9662e40b-a89f-4f94-9026-ce7554681659", "type": "concept", "title": "Collective action"}, {"id": "2315747e-a7c1-49c4-b3cf-e6f9c781bf0d", "type": "concept", "title": "Public goods"}, {"id": "15dac414-54ca-4310-8e9f-f452f562de13", "type": "concept", "title": "Free riding and enforcement"}], "description": "Global governance exists because some problems cross borders."}, {"id": "8c610867-8f10-4654-b9c0-2738958ac8b3", "type": "subtopic", "title": "Institutional design", "children": [{"id": "e05e735c-452f-480b-8a7f-9a4e5614a722", "type": "concept", "title": "Formal organizations"}, {"id": "c17c7c21-aa1b-4d83-a792-f7779276ea28", "type": "concept", "title": "Regimes"}, {"id": "413e733e-61f9-41b9-a567-2f25a0919169", "type": "concept", "title": "Informal networks and clubs"}], "description": "Institutions vary in membership, authority, legitimacy, and effectiveness."}, {"id": "3dd2060a-5fde-47f5-8198-e28bf605e28c", "type": "subtopic", "title": "Reform and legitimacy", "children": [{"id": "e1f008c6-6426-4ecb-99aa-b182e4ac4fe5", "type": "concept", "title": "Security Council reform"}, {"id": "5e756c5d-04b6-4c17-9f5a-936f825a4e37", "type": "concept", "title": "Accountability deficits"}, {"id": "3b6828cd-f452-4fec-871f-f65d26990343", "type": "concept", "title": "Representation of the Global South"}], "description": "Students evaluate whether global institutions are fair and effective."}]}, {"id": "4438a7ad-d162-46a9-9430-0107855db0b2", "type": "topic", "title": "Human Rights, Humanitarian Intervention, and Responsibility to Protect", "description": "Students analyze the tension between sovereignty, human dignity, atrocities, intervention, accountability, and selective enforcement.", "children": [{"id": "fe19af6f-8dfa-4be9-bd48-43159e67b3ef", "type": "subtopic", "title": "Human rights politics", "children": [{"id": "79df3be3-af0b-441b-b3f7-9882cfda204b", "type": "concept", "title": "Universal Declaration and treaty regimes"}, {"id": "87517ad4-d8be-4883-8c41-5af7a2faf6c8", "type": "concept", "title": "Monitoring and naming-and-shaming"}, {"id": "50f854fa-326c-48c3-8568-c6c51a69c79f", "type": "concept", "title": "Domestic repression and transnational advocacy"}], "description": "Rights are legal claims, moral claims, and political struggles."}, {"id": "5f4218bc-a7b9-46d8-ac59-b1efb7ab6310", "type": "subtopic", "title": "Humanitarian intervention", "children": [{"id": "34321788-000c-4488-a1eb-9c59d1b40086", "type": "concept", "title": "Responsibility to Protect"}, {"id": "a2581a0b-0a72-4f09-bb02-af16e5ea0d5f", "type": "concept", "title": "Selectivity and legitimacy"}, {"id": "ea4ed3af-14da-4033-891e-d6b98f2555c3", "type": "concept", "title": "Peacekeeping and peace enforcement"}], "description": "Intervention raises hard sovereignty and justice questions."}, {"id": "b93dc087-fc2f-45a5-a855-350f6b36a84c", "type": "subtopic", "title": "Accountability", "children": [{"id": "68a407ac-586e-4abd-8eb9-516b567a36c1", "type": "concept", "title": "International criminal law"}, {"id": "3d23aa95-2804-489a-89fe-f5235d12b26e", "type": "concept", "title": "Truth commissions"}, {"id": "0f2a3aee-57c9-44db-8ce6-b0c0222a9095", "type": "concept", "title": "Reparations and transitional justice"}], "description": "Post-conflict justice seeks to deter and repair harm."}]}, {"id": "eb95317c-ce60-429f-8684-459c1dcb091a", "type": "topic", "title": "Globalization, Transnational Actors, and Nonstate Power", "description": "This module explores corporations, NGOs, advocacy networks, diasporas, media, criminal networks, and social movements.", "children": [{"id": "e8ee05d1-f6f2-42f9-81c3-599aa0484b42", "type": "subtopic", "title": "Globalization", "children": [{"id": "ed09d5e2-5a84-4f00-b162-656bf560f2eb", "type": "concept", "title": "Flows of goods, people, capital, and information"}, {"id": "6e419822-4460-4f4e-833e-c0b3bb57b095", "type": "concept", "title": "Winners and losers"}, {"id": "0df59112-d96e-4b88-91ec-5586a14be4ca", "type": "concept", "title": "Backlash and nationalism"}], "description": "Students analyze integration across markets, cultures, technologies, and institutions."}, {"id": "ebf1f8bd-a02c-4050-b608-c27dd840f736", "type": "subtopic", "title": "Nonstate actors", "children": [{"id": "99eb05dc-93e6-49d3-8eaf-762909aeba6b", "type": "concept", "title": "Multinational corporations"}, {"id": "12ff55a5-173e-4ca6-b05f-1c142ddb61a6", "type": "concept", "title": "NGOs and advocacy networks"}, {"id": "665d855a-ea2e-4e50-8f67-df877790856e", "type": "concept", "title": "Terrorist and criminal organizations"}], "description": "States are central, but they do not act alone."}, {"id": "cae702de-e38d-4ba5-ac31-dc22f42ab471", "type": "subtopic", "title": "Networks and influence", "children": [{"id": "9b63be15-ca6d-4ab8-9209-53936550eb44", "type": "concept", "title": "Diasporas"}, {"id": "fdc5e028-3d20-46a0-aa8e-060e51646112", "type": "concept", "title": "Media and information campaigns"}, {"id": "7860bc48-b549-4ae5-b2da-b4f8ee181881", "type": "concept", "title": "Norm diffusion and social movements"}], "description": "Power can move through networks as well as armies."}]}, {"id": "f0ebe8a7-0e0f-4641-b4f7-9f310ce9a2e5", "type": "topic", "title": "Climate, Migration, Health, Technology, and Emerging Global Issues", "description": "Students learn how IR tools apply to cross-border problems that do not fit neatly into old security or economic categories.", "children": [{"id": "a2af05cb-d13b-4454-a85a-d1087e928845", "type": "subtopic", "title": "Climate politics", "children": [{"id": "ba304136-e22f-435a-9ec7-7beff425ede0", "type": "concept", "title": "Paris Agreement"}, {"id": "ed861415-834b-45a3-b0ff-0967662856fd", "type": "concept", "title": "Mitigation and adaptation"}, {"id": "712463e6-aac2-4802-a777-263428b35e06", "type": "concept", "title": "Climate finance and loss-and-damage debates"}], "description": "Climate is a collective-action, justice, and security problem."}, {"id": "47303a39-6fb3-4ca3-a5dc-c0291ffe5476", "type": "subtopic", "title": "Migration and health", "children": [{"id": "805c0bc3-9932-4c07-bc0c-a6954018f988", "t